const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const beijing = ee.Geometry.Point([116.4074, 39.9042]).buffer(50000); // 50km buffer around Beijing
  const period1_start = '2020-01-01';
  const period1_end = '2020-01-20';
  const period2_start = '2020-02-10';
  const period2_end = '2020-02-25';
  const band = 'tropospheric_NO2_column_number_density';

  // 2. Data Acquisition & Pre-processing Function
  const getMeanNO2 = function(startDate, endDate, geometry) {
    const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .select([band, 'qa_value'])
      .filterBounds(geometry)
      .filterDate(startDate, endDate);

    // Check for empty collection
    const size = collection.size().getInfo();
    if (size === 0) {
      return { 'mean': null, 'count': null, 'size': 0 };
    }

    // Mask for high-quality pixels (qa_value > 0.75 is recommended)
    const maskedCollection = collection.map(function(image) {
      const qaMask = image.select('qa_value').gt(0.75);
      return image.updateMask(qaMask);
    });

    const meanImage = maskedCollection.select(band).mean();

    // Perform reduction to get statistics
    const stats = meanImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: 3000,
      maxPixels: 1e9
    });

    return {
      'mean': stats.get(band + '_mean').getInfo(),
      'count': stats.get(band + '_count').getInfo(),
      'size': size
    };
  };

  // 3. Calculation for both periods
  const stats1 = getMeanNO2(period1_start, period1_end, beijing);
  const stats2 = getMeanNO2(period2_start, period2_end, beijing);

  // 4. Validation & Output
  console.log(`Period 1 (Jan 1-20, 2020) Img Count: ${stats1.size}`);
  console.log(`Period 2 (Feb 10-25, 2020) Img Count: ${stats2.size}`);

  if (stats1.size === 0 || stats2.size === 0) {
    console.log('Evidence: No images found for one or both periods.');
    console.log('A: Yes');
    return;
  }

  if (stats1.count === 0 || stats2.count === 0) {
    console.log(`Period 1 Valid Pixels: ${stats1.count}`);
    console.log(`Period 2 Valid Pixels: ${stats2.count}`);
    console.log('Evidence: No valid pixels after cloud/quality masking for one or both periods.');
    console.log('C2');
    return;
  }

  const no2_period1 = stats1.mean;
  const no2_period2 = stats2.mean;

  if (no2_period1 === null || no2_period2 === null) {
    console.log('Evidence: Calculation failed, result is null.');
    console.log('C3');
    return;
  }

  // Values are in mol/m^2, multiply by 1e5 for readability
  console.log(`Jan 1-20 Mean NO2 (x1e-5 mol/m^2): ${(no2_period1 * 1e5).toFixed(2)}`);
  console.log(`Feb 10-25 Mean NO2 (x1e-5 mol/m^2): ${(no2_period2 * 1e5).toFixed(2)}`);

  if (no2_period2 < no2_period1) {
    console.log('Evidence: Mean NO2 in the February period was lower than in the January period.');
    console.log('A: Yes');
  } else {
    console.log('Evidence: Mean NO2 in the February period was not lower than in the January period.');
    console.log('B: No');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred:', err);
    console.log('D');
});
